-- ============================================================================
-- 미니 프로젝트 1 (MP1) - 두두자격지원센터 Supabase 전체 데이터베이스 스키마
-- (참고 자료: data/01_form_정책.md, data/02_접수DB_필드명세.md, draft_100 데이터셋)
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. 통합 원서접수 테이블 (applications) : 메인 접수 웹페이지 & 접수 어드민 연동
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.applications (
    id BIGSERIAL PRIMARY KEY,
    receipt_number TEXT,                          -- 접수번호 (예: DN2026772247, DP2026873295, DH2026428626)
    name TEXT NOT NULL,                           -- 성명
    birth_date DATE,                              -- 생년월일
    gender TEXT,                                  -- 성별 (남/여)
    phone TEXT NOT NULL,                          -- 연락처 (010-xxxx-xxxx)
    qualification TEXT NOT NULL,                  -- 자격종목명 (한식조리, 지게차, 굴착기, 전기, 요양보호사, 위생사, 손해평가사, 공인중개사)
    grade TEXT DEFAULT '기능사',                   -- 등급 (기능사/전문자격/보건자격)
    exam_type TEXT DEFAULT '상시CBT',             -- 시험유형 (상시CBT/정기/연1회)
    exam_stage TEXT DEFAULT '필기',               -- 시험구분/차수 (필기/1차/2차)
    exam_round INT,                               -- 정기 회차 (1~4, 상시는 NULL)
    exam_region TEXT,                             -- 시험지역 (서울/부산/대구 등 17개 광역)
    exam_center TEXT,                             -- 시험장 / 시험센터명
    exam_date DATE,                               -- 시험일자
    exam_session TEXT,                            -- 교시/시간대 (1~5교시, AM/PM 등)
    fee_amount INT DEFAULT 14500,                 -- 원 응시수수료
    fee_discount_type TEXT DEFAULT '없음',         -- 감면유형 (없음/장애인/기초수급/국가유공자/차상위)
    fee_discount_amount INT DEFAULT 0,            -- 감면금액
    fee_final INT DEFAULT 14500,                  -- 최종 결제금액
    payment_method TEXT DEFAULT '신용카드',        -- 결제수단 (신용카드/계좌이체/가상계좌)
    payment_status TEXT DEFAULT '완료',            -- 결제상태 (대기/완료/실패/환불)
    status TEXT DEFAULT '접수완료',                -- 접수상태 (접수완료/결제대기/취소/환불)
    usage_context TEXT,                           -- 접수 사용 맥락 (본인단독/가족보조/복지관 등)
    training_institution TEXT,                    -- 교육기관명 (보건자격 수료기관)
    training_hours INT DEFAULT 0,                 -- 교육이수시간 (요양보호사 240 등)
    memo TEXT,                                    -- 어드민 관리자 메모
    created_at TIMESTAMPTZ DEFAULT TIMEZONE('Asia/Seoul', NOW())
);

-- applications RLS 정책 설정 (공개 접근 허용)
ALTER TABLE public.applications ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public select on applications" ON public.applications;
DROP POLICY IF EXISTS "Allow public insert on applications" ON public.applications;
DROP POLICY IF EXISTS "Allow public update on applications" ON public.applications;
DROP POLICY IF EXISTS "Allow public delete on applications" ON public.applications;

CREATE POLICY "Allow public select on applications" ON public.applications FOR SELECT USING (true);
CREATE POLICY "Allow public insert on applications" ON public.applications FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow public update on applications" ON public.applications FOR UPDATE USING (true);
CREATE POLICY "Allow public delete on applications" ON public.applications FOR DELETE USING (true);


-- ----------------------------------------------------------------------------
-- 2. FAQ 및 사내 안내 규정 테이블 (faq_documents) : AI 챗봇 & FAQ 어드민 연동
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.faq_documents (
    id BIGSERIAL PRIMARY KEY,
    category TEXT NOT NULL,                       -- 구분 (응시료, 일정, 결제/환불, 유효기간, 시험준비물, 접수방법, 실기문의, 확인불가)
    qualification TEXT DEFAULT '공통',            -- 대상 자격종목
    question TEXT NOT NULL,                       -- 질문 / 규정 제목
    keywords TEXT NOT NULL,                       -- 검색 및 시니어 유의어 키워드 (쉼표 구분)
    answer TEXT NOT NULL,                         -- 챗봇 응답 내용 (사내 규정 원장 기반)
    is_unknown BOOLEAN DEFAULT false,             -- 확인 불가 항목 여부 (true 시 '모르겠습니다' 강제 거절)
    updated_at TIMESTAMPTZ DEFAULT TIMEZONE('Asia/Seoul', NOW())
);

-- faq_documents RLS 정책 설정
ALTER TABLE public.faq_documents ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public select on faq_documents" ON public.faq_documents;
DROP POLICY IF EXISTS "Allow public insert on faq_documents" ON public.faq_documents;
DROP POLICY IF EXISTS "Allow public update on faq_documents" ON public.faq_documents;
DROP POLICY IF EXISTS "Allow public delete on faq_documents" ON public.faq_documents;

CREATE POLICY "Allow public select on faq_documents" ON public.faq_documents FOR SELECT USING (true);
CREATE POLICY "Allow public insert on faq_documents" ON public.faq_documents FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow public update on faq_documents" ON public.faq_documents FOR UPDATE USING (true);
CREATE POLICY "Allow public delete on faq_documents" ON public.faq_documents FOR DELETE USING (true);


-- ----------------------------------------------------------------------------
-- 3. FAQ 규정 원장 데이터 시딩 (MP1_발주문서_세트.pdf & 02_안내규정.md 기반 23개 전수 원장)
-- ----------------------------------------------------------------------------
DELETE FROM public.faq_documents;

INSERT INTO public.faq_documents (id, category, qualification, question, keywords, answer, is_unknown) VALUES
(1, '응시료', '3대 기능사 공통 (한식, 지게차, 굴착기)', '한식조리, 지게차, 굴착기운전기능사 필기 응시료는 얼마인가요?', '응시료,접수비,시험비,비용,얼마,한식,한식조리,지게차,굴착기,포크레인,수수료,돈,기능사,금액,얼마예요', '어르신, 한식조리기능사, 지게차운전기능사, 굴착기운전기능사 3종 모두 필기 응시료는 14,500원으로 동일합니다. (기초생활수급자, 등록장애인, 국가유공자, 차상위계층 대상자는 50% 감면된 7,250원입니다.)', false),
(2, '응시료', '국가기술자격 실기 수수료', '기능사 실기시험 응시료(수수료)는 얼마인가요?', '실기,실기비용,실기응시료,실기수수료,2차비용,실습비,전기기능사실기,한식실기,지게차실기,굴착기실기', '국가기술자격 실기시험 수수료는 종목마다 다릅니다. 한식조리기능사는 26,900원, 지게차운전기능사는 25,200원, 굴착기운전기능사는 27,800원이며, 전기기능사 실기는 재료비 등으로 인해 106,200원입니다.', false),
(3, '응시료', '사회적 배려계층 감면', '응시료 50% 감면 대상자는 누구이고 얼마를 내나요?', '감면,50%,할인,기초수급자,차상위,국가유공자,장애인,면제,혜택', '기초생활수급자, 등록장애인, 국가유공자, 차상위계층에 해당하시는 어르신께서는 정규 필기 응시료(14,500원)의 50%가 감면되어 7,250원만 결제하시면 됩니다.', false),
(4, '일정/방식', '3대 기능사 공통 (상시 CBT)', '한식, 지게차, 굴착기 시험 접수 기간과 시험 방식은 어떻게 되나요?', '접수기간,언제접수,상시,CBT,컴퓨터시험,시험방식,신청기간,날짜,시험일정', '한식조리, 지게차, 굴착기 3대 종목은 별도의 정기 접수 기간 없이 상시 CBT(컴퓨터 시험)로 운영됩니다. 시험장에 빈자리가 있으면 원하시는 날짜와 교시를 선택해 언제든 접수하실 수 있습니다.', false),
(5, '일정/방식', '전기기능사 (정기 회차)', '전기기능사 시험 일정과 접수 기간은 어떻게 되나요?', '전기기능사,전기,정기시험,정기회차,4회,전기일정,전기접수', '전기기능사는 연 4회 정기 시험으로 진행됩니다. 2026년 기준 가장 가까운 제4회 필기 원서접수는 8월 24일부터 8월 27일까지이며, 필기시험은 9월 16일부터 9월 21일까지 치러집니다. (빈자리 추가접수는 9월 10일~11일)', false),
(6, '일정/방식', '요양보호사 (국시원 상시)', '요양보호사 시험 접수는 언제까지 해야 하나요?', '요양보호사,요양사,국시원,요양접수,요양일정,요양보호사접수', '요양보호사 시험은 국시원 상시시험 사이트에서 접수하며, 원하시는 시험일 기준 7일 전까지 접수를 마치셔야 합니다. 합격자 발표는 시험 다음 날 오전 10시 이후(주말·공휴일 제외)에 공지됩니다.', false),
(7, '일정/방식', '손해평가사 / 공인중개사 (연 1회)', '손해평가사, 공인중개사 올해 1차 시험 접수할 수 있나요?', '손해평가사,공인중개사,부동산,1차,올해접수,전문자격', '손해평가사(제12회 1차, 4월 마감)와 공인중개사(제37회 1차, 8월 마감)는 모두 연 1회 시행되는 시험으로 올해 1차 원서접수가 이미 마감되었습니다. 따라서 올해는 접수가 불가능하며 내년 시험에 응시하셔야 합니다.', false),
(8, '일정/방식', '접수 시작 시간', '원서접수 시작 시각은 몇 시인가요?', '접수시간,몇시,시작시간,오전9시,오전10시,오픈시간', '국가기술자격 기능사(한식, 지게차, 굴착기, 전기)는 첫날 오전 10:00에 접수가 시작되며, 전문자격(손해평가사, 공인중개사)은 전용 사이트에서 오전 09:00에 시작됩니다. 선착순 마감이므로 시간을 잘 확인하셔야 합니다.', false),
(9, '합격발표', '3대 기능사 공통 (상시 CBT)', '합격자 발표는 언제 나오나요?', '합격,발표,언제나와,결과,점수,당일,합격자,합격여부', '한식조리, 지게차, 굴착기운전기능사 상시 CBT 시험은 컴퓨터로 치러지므로, 시험 종료 버튼을 누르면 그 자리에서 즉시 점수와 합격 여부를 확인하실 수 있습니다.', false),
(10, '유효기간', '국가기술자격 기능사 공통', '필기시험에 합격하면 유효기간이 얼마나 되나요?', '유효기간,필기면제,면제기간,2년,필기합격,실기언제까지', '국가기술자격(기능사)은 필기시험 합격일로부터 2년간 필기시험이 면제됩니다. 2년 이내에 원하시는 실기시험에 접수하여 응시하시면 됩니다.', false),
(11, '시험시간', '상시 CBT 교시 안내', '하루에 몇 부(교시)까지 시험이 있고 시간은 얼마나 걸리나요?', '교시,몇부,시간,시험시간,1부,2부,3부,4부,5부,60분,소요시간', '상시 CBT 시험은 기능사 기준 시험시간이 60분이며, 하루에 1부(09:00), 2부(11:00), 3부(13:00), 4부(15:00), 5부(17:00) 총 5개 교시로 나뉘어 진행됩니다.', false),
(12, '시험준비물', '시험장 지참물 및 반입 규정', '시험 당일 준비물과 시험실에 가지고 들어갈 수 있는 물품은 무엇인가요?', '준비물,신분증,수험표,필기도구,스마트폰,휴대폰,스마트워치,시계,계산기,지참물', '시험 당일에는 실물 신분증(주민등록증·운전면허증 등), 수험표, 흑색 필기구를 반드시 지참하셔야 합니다. 시험실에는 신분증, 수험표, 필기구, 수정테이프, 일반시계, 계산기, 간식 등 8가지만 허용되며, 스마트폰·스마트워치 등 전자기기는 소지 시 즉시 시험이 무효 처리됩니다.', false),
(13, '결제/환불', '정규 환불 규정', '접수 후 취소하면 환불을 얼마나 받을 수 있나요?', '환불,취소,환불금액,전액환불,50%환불,환불기간,토스페이먼츠', '원서접수 기간 내 취소 시에는 100% 전액 환불되며, 접수 마감 후부터 해당 시험 시작 5일 전까지는 50%가 환불됩니다. (시험 시작 4일 전부터는 환불 불가). 환불금은 최대 7일 이내 ''토스페이먼츠'' 명의로 입금됩니다.', false),
(14, '결제/환불', '사후 특별 환불 (100%)', '시험을 못 보게 되었는데 사후 환불(100%)을 받을 수 있는 사유가 있나요?', '사후환불,입원,사망,상,전염병,격리,천재지변,교통두절,특별환불', '접수기간 이후라도 직계가족(부모·배우자·자녀 등) 사망, 본인의 질병·사고 입원, 국가 전염병 격리, 천재지변으로 인한 교통 두절 등의 불가피한 사유가 있을 경우 증빙서류를 제출하시면 100% 전액 환불받으실 수 있습니다.', false),
(15, '결제/환불', '가상계좌 입금 기한', '가상계좌로 결제할 때 언제까지 입금해야 하나요?', '가상계좌,무통장,입금기한,언제까지입금,자동취소', '가상계좌는 접수 시점에 따라 기한이 다릅니다. 마감일 전날 13시 이전 접수는 당일 14시까지, 13시 이후 접수는 익일 14시까지 입금하셔야 합니다. 마감일 당일 13시 이후에는 가상계좌 채번이 불가하므로 카드나 실시간 계좌이체를 이용하셔야 합니다.', false),
(16, '접수방법', '공통 (시니어 무료 대행)', '컴퓨터나 스마트폰 사용이 어려운데 전화나 방문으로도 접수가 가능한가요?', '전화접수,방문접수,접수대행,도와줘,신청해줘,어려워,인터넷못해', '네 어르신, 인터넷 접수가 어려우신 경우 성함과 연락처를 남겨주시면 저희 두두자격지원센터 상담 직원이 친절하게 무료로 원서접수 대행을 도와드립니다.', false),
(17, '확인불가', '요양보호사', '요양보호사 자격증 응시료는 얼마인가요?', '요양보호사응시료,요양보호사비용,요양사수수료,요양보호사돈', '죄송합니다. 요양보호사 응시료 금액은 사내 안내 규정 문서에 명시되어 있지 않아 정확한 안내가 어렵습니다. (국시원 홈페이지를 통해 확인해 주시기 바랍니다.)', true),
(18, '확인불가', '위생사', '위생사 자격증 시험 일정과 응시료는 어떻게 되나요?', '위생사,위생사일정,위생사응시료,위생사비용,위생사수수료', '죄송합니다. 위생사 시험 일정 및 응시료는 사내 안내 규정에 기재되어 있지 않아 답변드릴 수 없습니다. (국시원 대표 홈페이지에서 확인 부탁드립니다.)', true),
(19, '확인불가', '손해평가사 / 공인중개사', '손해평가사 또는 공인중개사 1차 시험 응시료는 얼마인가요?', '손해평가사응시료,공인중개사응시료,손해평가사비용,공인중개사비용,손해평가사수수료,공인중개사수수료', '죄송합니다. 손해평가사 및 공인중개사 1차 응시료 금액은 사내 규정 원장에 등록되어 있지 않아 안내가 불가합니다. (큐넷 전문자격 홈페이지를 참조해 주십시오.)', true),
(20, '확인불가', '요양보호사 교육 이수', '요양보호사 응시자격 교육 이수 시간은 몇 시간인가요?', '요양보호사이수시간,요양보호사교육시간,요양보호사자격조건,요양보호사이수', '죄송합니다. 요양보호사 교육 이수 시간 및 상세 응시자격 요건은 사내 규정 문서에 확인되지 않아 안내가 어렵습니다.', true),
(21, '확인불가', '공인중개사 1차 면제', '공인중개사 1차 시험에 합격하면 2차 면제 기간이 정말 1년인가요?', '공인중개사면제,공인중개사1년,공인중개사유효기간', '죄송합니다. 공인중개사 1차 합격에 따른 면제 기간은 사내 규정 원장에서 공식 확인되지 않았으므로 정확한 답변을 드릴 수 없습니다.', true),
(22, '확인불가', '시험장 시설/주차', '시험장에 주차장이 있나요? 주차나 셔틀버스가 지원되나요?', '주차,주차장,차댈곳,셔틀버스,대중교통,주차비', '죄송합니다. 시험장별 주차 가능 여부나 셔틀버스 운행 정보는 사내 안내 규정에 나와 있지 않아 안내가 어렵습니다. 시험장 본부로 직접 문의해 주시기 바랍니다.', true),
(23, '확인불가', '개인 상담', '제가 이번 시험에 합격할 수 있을까요? 교재나 강의를 추천해 주세요.', '합격할까요,붙을수있나요,교재추천,학원추천,강의추천,난이도', '죄송합니다. 개인의 시험 합격 가능성이나 사설 교재/강의 추천은 사내 규정 안내 범위를 벗어나 답변드릴 수 없습니다. 어르신의 도전을 진심으로 응원합니다!', true);


